export class NetworkRoom {
 constructor({onState,onError}){this.onState=onState;this.onError=onError;this.session=null;this.state=null;this.seq=0;this.input={};this.pending={};this.closed=false;this.running=false;this.retry=null;this.lastOk=0;}
 async call(action,payload={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('/api/rooms/'+action,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...this.session,...payload}),signal:controller.signal});const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error||'Unable to connect to the room.'),{status:r.status});return data;}catch(e){if(e.name==='AbortError')throw new Error('Connection timed out. Check your connection.');throw e;}finally{clearTimeout(timeout);}}
 accept(data){if(this.state&&data.revision<this.state.revision)return;this.lastOk=performance.now();this.state=data;this.onState(data);}
 async enter(action,options){const data=await this.call(action,options);this.session={code:data.code,token:data.token};this.closed=false;this.accept(data);this.pump();return data;}
 capture(input){for(const k of ['jump','special'])if(input[k])this.pending[k]=true;if(input.activate)this.pending.activate=input.activate;if(input.command!==undefined&&input.command!==null)this.pending.command=input.command;this.input={...input,jump:false,special:false,activate:null,command:null};}
 async pump(){if(this.closed||!this.session)return;const start=performance.now();this.running=true;try{const payload=this.retry||{seq:++this.seq,input:{...this.input,...this.pending}};if(!this.retry)this.pending={};this.retry=payload;const data=await this.call('sync',payload);this.retry=null;this.accept(data);}catch(e){this.onError(e.message);if([401,404].includes(e.status)){this.closed=true;this.running=false;return;}}this.running=false;if(!this.closed)this.timer=setTimeout(()=>this.pump(),Math.max(10,(this.state?.phase==='playing'?90:700)-(performance.now()-start)));}
 async start(){const data=await this.call('start');this.accept(data);}
 resetInput(){this.input={};this.pending={};this.retry=null;if(this.session&&!this.closed){const body=JSON.stringify({...this.session,seq:++this.seq,input:{}});fetch('/api/rooms/sync',{method:'POST',headers:{'content-type':'application/json'},body,keepalive:true}).catch(()=>{});}}
 async leave(){this.closed=true;clearTimeout(this.timer);if(this.session)try{await this.call('leave')}catch{}this.session=null;}
}
